    checkpoint.update(recorded_at=now,status=review['status'],baseline_answers_bounded_correct=2,concise_loading_answers_rejected=2,separate_concise_playability_answer_correct=True,concise_default_promoted=False,canonical_prompt_restored=True,SDK_reported_seconds=[[s['SDK_reported_seconds']for s in group]for group in reviewed],known_compute_jobs='terminal',model_idle=True,new_training=False,default_promoted=False,native_new_response_verified=False,review=str(ROOT/'verification/disc-loading-yield-review.json'),transcript=str(audit/'prompts-and-responses.txt'),next_synchronization_workmap=str(session/'resource-synchronization-fullCPU-workmap.json'));checkpoint['evidence']=list(dict.fromkeys(checkpoint['evidence']+['verification/disc-loading-yield-MCP-check.json','verification/disc-loading-yield-review.json',str((audit/'prompts-and-responses.txt').relative_to(ROOT))]));save(ROOT/'verification/disc-loading-yield-checkpoint.json',checkpoint)
